from pathlib import Path
root=Path('/mnt/data/technical-contracting-site')
services=[('Plumbing & Sanitary Installation','Reliable plumbing installation and sanitary fitting solutions for residential and commercial spaces.','plumbing-sanitary-installation','https://images.unsplash.com/photo-1621905251918-48416bd8575a?auto=format&fit=crop&w=1200&q=85','Plumbing and sanitary installation helps keep a property practical, comfortable, and ready for everyday use. Scope can include installation, replacement, fixture fitting, and coordination with other agreed works.','Typical work may include sanitary fixtures, taps, pipework, drainage connections, and fitting replacements, subject to site assessment and project scope.'),('Painting Services','Interior and exterior painting with careful preparation and a clean, consistent finish.','painting-services','https://images.unsplash.com/photo-1562259949-e8e7689d7828?auto=format&fit=crop&w=1200&q=85','A good paint finish starts with suitable surface preparation. Our proposed painting service covers planned preparation, application, and finishing for spaces that need a refresh or a new look.','Work may include surface inspection, minor preparation, suitable primer where required, and painting of agreed interior or exterior areas.'),('Plastering & Wall Finishing','Wall preparation and plastering services designed to create smooth, ready-to-finish surfaces.','plastering-wall-finishing','https://images.unsplash.com/photo-1503387762-592dead58ef4?auto=format&fit=crop&w=1200&q=85','Plastering and wall finishing create a consistent base for decorating and other finishing work. The right approach depends on the surface condition, environment, and final finish required.','Potential tasks include surface preparation, patch repairs, plaster application, levelling, and preparation for painting or other finishes.'),('Floor & Wall Tiling','Practical tile installation for floors and walls with attention to alignment and finishing.','floor-wall-tiling','https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85','Tiling can improve the durability, appearance, and ease of maintenance of a space. Planning the layout and preparing the substrate are important parts of achieving a neat result.','Depending on the project, work may include substrate preparation, layout planning, tile fixing, grouting, and finishing around edges and fixtures.'),('Building Renovation','Renovation support to refresh existing spaces and coordinate agreed improvement works.','building-renovation','https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1200&q=85','Renovation projects benefit from clear scope, practical sequencing, and regular communication. We can help assess the required improvements and define a workable scope before work begins.','Renovation tasks vary by property and may include agreed finishing, repair, tiling, painting, and other improvement work after assessment.'),('Technical Maintenance','Responsive maintenance support for common building and property requirements.','technical-maintenance','https://images.unsplash.com/photo-1581092921461-eab62e97a780?auto=format&fit=crop&w=1200&q=85','Planned maintenance and timely repairs help keep properties functional and presentable. Each request should be assessed to establish the cause, scope, access requirements, and suitable next steps.','Maintenance requests can be reviewed for repair needs, minor replacements, finishing issues, and other agreed property tasks.')]
def layout(title,desc,body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{desc}"><meta name="theme-color" content="#102a43"><link rel="canonical" href="https://www.example.com/{'/' if title=='Home' else ''}"><link rel="stylesheet" href="/assets/styles.css"><title>{title} | NOVA Technical Contracting</title><script type="application/ld+json">{{"@context":"https://schema.org","@type":"GeneralContractor","name":"NOVA Technical Contracting","description":"Technical contracting and property improvement services in the UAE","url":"https://www.example.com"}}</script></head><body><div id="header"></div><main data-title="{title}">{body}</main><div id="footer"></div><script src="/assets/site.js" defer></script></body></html>'''
def pagehero(title,desc): return f'<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="/index.html">Home</a> &nbsp;/&nbsp; {title}</div><h1>{title}</h1><p>{desc}</p></div></section>'
# Home
body='''<section class="hero"><div class="container"><div class="hero-inner reveal"><span class="eyebrow">Technical contracting · UAE</span><h1>Reliable contracting.<br>Quality in every detail.</h1><p>Practical technical contracting and property improvement solutions, delivered with a focus on careful workmanship, clear communication, and dependable service.</p><div class="hero-actions"><a class="btn" href="/services.html">Explore Our Services <span>→</span></a><a class="btn btn-outline" href="/contact.html">Request a Quote</a></div></div></div></section><section class="trust-strip"><div class="container"><strong>Solutions shaped around your property and project needs.</strong><span>Residential · Commercial · Property Improvements</span></div></section><section class="section"><div class="container two-col"><div class="photo-panel"><img src="https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1100&q=85" alt="Modern finished interior with quality surfaces" loading="lazy"><div class="photo-note"><strong>Built around your needs</strong><span>Clear scope. Careful delivery.</span></div></div><div><span class="eyebrow">Who we are</span><h2>Practical solutions for better spaces</h2><p>Every property has its own requirements. We take a considered approach to technical contracting, from understanding the work needed to planning the details and completing the agreed scope.</p><p>Our website outlines common service areas and helps clients start a conversation about their project. Final service availability, timing, and pricing are confirmed after reviewing the specific requirements.</p><a class="text-link" href="/about.html">Learn about our approach <span>→</span></a></div></div></section><section class="section bg-pale"><div class="container"><div class="section-head"><span class="eyebrow">What we do</span><h2>Technical contracting services</h2><p>Explore the service categories below. Each project is assessed individually so the proposed scope can match the property and its requirements.</p></div><div class="service-grid">SERVICE_CARDS</div><div style="text-align:center;margin-top:35px"><a class="btn btn-dark" href="/services.html">View All Services <span>→</span></a></div></div></section><section class="section"><div class="container"><div class="section-head center"><span class="eyebrow">Our approach</span><h2>A straightforward process</h2><p>Good project delivery starts with clarity. We aim to make the steps easy to understand from the first enquiry.</p></div><div class="process-grid"><article class="process-card"><h3>Understand</h3><p>Discuss your property, priorities, and expected outcome.</p></article><article class="process-card"><h3>Assess</h3><p>Review the scope, site conditions, and practical requirements.</p></article><article class="process-card"><h3>Plan</h3><p>Agree on the work, quotation, timing, and next steps.</p></article><article class="process-card"><h3>Deliver</h3><p>Carry out the agreed work and review the completed scope.</p></article></div></div></section><section class="section bg-pale"><div class="container"><div class="section-head"><span class="eyebrow">Project inspiration</span><h2>Work that improves everyday spaces</h2><p>Use this section to showcase real completed projects as photography and approved project details become available.</p></div><div class="project-grid"><article class="project"><img src="https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=900&q=80" alt="Interior finishing inspiration" loading="lazy"><div class="project-label"><strong>Interior finishing</strong><span>Project gallery placeholder</span></div></article><article class="project"><img src="https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=900&q=80" alt="Residential renovation inspiration" loading="lazy"><div class="project-label"><strong>Property improvements</strong><span>Project gallery placeholder</span></div></article><article class="project"><img src="https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=900&q=80" alt="Construction work in progress" loading="lazy"><div class="project-label"><strong>Technical works</strong><span>Project gallery placeholder</span></div></article></div><p style="font-size:.82rem;margin-top:15px">Images are illustrative only and are not represented as company-completed projects.</p></div></section><section class="cta-band"><div class="container"><div><h2>Planning a repair, upgrade, or renovation?</h2><p>Tell us what you need and start a conversation about your project.</p></div><a class="btn" href="/contact.html">Discuss Your Project <span>→</span></a></div></section>'''.replace('SERVICE_CARDS','SERVICE_CARDS')
