# service pages
for name,short,slug,img,desc,scope in services:
    body=pagehero(name,short)+f'''<section class="section"><div class="container service-detail"><article><img src="{img}" alt="{name} service" loading="lazy"><span class="eyebrow">Service overview</span><h2>{name} for your property</h2><p>{desc}</p><p>{short} The exact method, materials, schedule, and price depend on site conditions and the work agreed with the client.</p><h3>What can the work involve?</h3><p>{scope}</p><ul class="check-list"><li>Discuss the required outcome and areas involved.</li><li>Review site conditions and any preparation needed.</li><li>Confirm the scope, materials, timing, and quotation before work begins.</li><li>Agree on finishing details and handover expectations.</li></ul><h3>Request a service assessment</h3><p>Share a short description of the work, the property type, and any relevant photos or measurements. This helps establish the information needed for the next step.</p><div style="margin-top:25px"><a class="btn" href="/contact.html">Request a Quote →</a></div><section style="margin-top:48px"><h2>Frequently asked questions</h2><div class="faq-list"><details><summary>Can I request a quotation for this service?</summary><p>Yes. Send the project details through the contact page. The company should confirm availability and any site-assessment requirements before providing a final quotation.</p></details><details><summary>How long will the work take?</summary><p>Timing depends on the area, condition of the site, materials, access, and agreed scope. A schedule can be discussed once these details are reviewed.</p></details><details><summary>Do you provide this service throughout the UAE?</summary><p>Service coverage should be confirmed directly. Include your property location when making an enquiry.</p></details></div></section></article><aside class="sidebar"><h3>Related services</h3>{''.join(f'<a href="/services/{s[2]}.html">{s[0]} ↗</a>' for s in services if s[2]!=slug)}<div style="margin-top:24px"><h3>Need help with a project?</h3><p>Share your requirements and request a quotation.</p><a class="btn btn-dark" href="/contact.html">Contact Us →</a></div></aside></div></section>'''
    (root/'services'/f'{slug}.html').parent.mkdir(exist_ok=True)
    (root/'services'/f'{slug}.html').write_text(layout(name,f'{name} in the UAE. Learn about typical scope, property requirements, and how to request a quotation.',body))
