body=pagehero('Contact Us','Tell us a little about your project and the service you are looking for.')+'''<section class="section"><div class="container contact-grid"><div><span class="eyebrow">Start a conversation</span><h2>How can we help?</h2><p>Share the type of property, the service you need, and a short description of the work. Contact details and availability should be confirmed before a site visit or booking.</p><div class="contact-item"><div class="contact-icon">↗</div><div><strong>Project enquiries</strong><span>Use the form to outline your requirements.</span></div></div><div class="contact-item"><div class="contact-icon">⌖</div><div><strong>Service area</strong><span>UAE — confirm location coverage when enquiring.</span></div></div><div class="contact-item"><div class="contact-icon">✉</div><div><strong>Email</strong><a href="mailto:info@example.com">info@example.com (demo address)</a></div></div><p style="font-size:.84rem">Before launch, replace the demo email and add the company's verified phone number, WhatsApp, and office address if applicable.</p></div><div class="form-card"><h3>Request a quotation</h3><p>Fields marked * are required.</p><form id="contact-form"><div class="form-grid"><div class="field"><label for="name">Full name *</label><input id="name" name="name" required autocomplete="name" placeholder="Your name"></div><div class="field"><label for="phone">Phone number *</label><input id="phone" name="phone" required autocomplete="tel" placeholder="Your contact number"></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label for="service">Service required *</label><select id="service" name="service" required><option value="">Choose a service</option><option>Plumbing & Sanitary Installation</option><option>Painting Services</option><option>Plastering & Wall Finishing</option><option>Floor & Wall Tiling</option><option>Building Renovation</option><option>Technical Maintenance</option><option>Other / Not sure</option></select></div><div class="field full"><label for="location">Property location</label><input id="location" name="location" placeholder="Area / emirate"></div><div class="field full"><label for="details">Project details *</label><textarea id="details" name="details" required placeholder="Describe the work you need..."></textarea></div><div class="field full"><button class="btn" type="submit">Submit Enquiry →</button><div class="form-status" role="status" aria-live="polite"></div></div></div></form></div></div></section>'''
